# math_utils.py — the code we want to test
def add(a, b):
    return a + b

def divide(a, b):
    if b == 0:
        raise ValueError('Cannot divide by zero')
    return a / b

def clamp(value, minimum, maximum):
    return max(minimum, min(value, maximum))

# test_math_utils.py — pytest finds files starting with test_
import pytest
from math_utils import add, divide, clamp

# Test functions must start with test_
def test_add_positive_numbers():
    assert add(2, 3) == 5

def test_add_negative_numbers():
    assert add(-1, -1) == -2

def test_add_returns_correct_type():
    result = add(1, 2)
    assert isinstance(result, int)

def test_divide_normal():
    assert divide(10, 2) == 5.0

def test_divide_by_zero_raises():
    with pytest.raises(ValueError, match='Cannot divide by zero'):
        divide(10, 0)

def test_clamp_below_min():
    assert clamp(-5, 0, 100) == 0

def test_clamp_above_max():
    assert clamp(150, 0, 100) == 100

def test_clamp_within_range():
    assert clamp(50, 0, 100) == 50

# Run with: pytest test_math_utils.py -v

