import pytest

# Fixture: set up reusable test data
@pytest.fixture
def sample_users():
    return [
        {'id': 1, 'name': 'Alice', 'active': True},
        {'id': 2, 'name': 'Bob',   'active': False},
        {'id': 3, 'name': 'Carol', 'active': True},
    ]

@pytest.fixture
def user_db(sample_users):
    db = UserDatabase()
    for user in sample_users:
        db.add(user)
    return db

# Fixtures are injected by name
def test_active_users_count(user_db):
    active = user_db.get_active_users()
    assert len(active) == 2

def test_find_user_by_id(user_db):
    user = user_db.find(1)
    assert user['name'] == 'Alice'

# Parametrize — run one test with multiple inputs
@pytest.mark.parametrize('value,expected', [
    (0, 0), (1, 1), (5, 120), (10, 3628800)
])
def test_factorial(value, expected):
    from math import factorial
    assert factorial(value) == expected

